"""specs_u69_66.py - area 69, group 66 (slice 8): 0x628fc0, a DBCS-style markup tokenizer (cdecl: tab, start, end, out).
Inputs: 60% from a curated list (one representative per reached state-machine label, found by a coverage search over a Python model of the
port's control flow), 40% random with the same kind of distribution. The class table (tab+0x4c+byte) is set per case.
The helper 0x62a690 is a GUESS stub: it logs (end-start) and its return (-1, 0 or 1), and writes start+2 through its out pointer.
Only integers are logged; pointers are never logged. Every label of the port is reached by some curated input (the targeted search added the last five, plus two survivor states)."""
from pilot import S
from ckit import rnd


CURATED = [
    ('', 'ddfc'),
    ('', '6400'),
    ('', '4300'),
    ('', 'c4801f'),
    ('', 'ca000e'),
    ('', '4600'),
    ('', 'e700ed'),
    ('', '39003d005ef7'),
    ('', '39003d005ed8'),
    ('', 'bf006700badce4d9d600'),
    ('', 'bf006700baffe4d9d600'),
    ('', '60008300720065d8e05cfe'),
    ('', '60008300720065d8e05c09'),
    ('', 'd800fb0029e97f171fb65ff9d88cf3456800eaf69100e800'),
    ('', '39003d005ef73d'),
    ('', '8900'),
    ('', '4600'),
    ('', '35d8'),
    ('', '4e00'),
    ('', '1d00c700e9'),
    ('', 'f20056'),
    ('', '2400f500c500f5007100'),
    ('', '7c007a000bf0620045002d0023'),
    ('', '5600d1003ada19d874f2dc001c00a8008e2268'),
    ('', '3b00a5008a0063004900'),
    ('', '7c007a000bf0620045002d0023'),
    ('', '3b00a5008a0063003e00'),
]

_BYTES = [0x00, 0x3e, 0x09, 0x0a, 0x0d, 0x0e, 0x0c, 0x15, 0x20, 0x41, 0x5b, 0x7f, 0x81, 0x98, 0xd8, 0xe0, 0xf0, 0xfe, 0xff]


def _tok(c):
    e = c.emu
    r = c.rng
    tab = rnd(c, 0x200)
    pad = 0x104
    if r.random() < 0.6:
        cls_hex, data_hex = CURATED[r.randrange(len(CURATED))]
        cls = bytearray.fromhex(cls_hex)
        data = bytearray.fromhex(data_hex)
    else:
        cls = bytearray(r.randrange(0, 0x1e) if r.random() < 0.6 else r.randrange(5, 0x1e) for _ in range(256))
        cls[0] = 8
        n = r.randrange(1, 48)
        data = bytearray(r.choice(_BYTES) if r.random() < 0.6 else r.getrandbits(8) for _ in range(n))
        for i in range(0, len(data) - 1, 2):
            k = r.random()
            if k < 0.4:
                data[i + 1] = 0
            elif k < 0.7:
                data[i + 1] = r.randrange(0xd8, 0x100)
    n = len(data)
    e.wbytes(tab + 0x4c, bytes(cls))
    buf = rnd(c, n + pad + 4)
    e.wbytes(buf, bytes(data) + bytes(pad + 4))
    end = buf + n
    out = rnd(c, 8)

    def stub(e, res):
        start = e.arg32(1)
        endp = e.arg32(2)
        outp = e.arg32(3)
        first = e.rbytes(start, 1)[0]
        rv = (first % 3) - 1
        e.calllog.append(('t62a690', (endp - start) & 0xffffffff, rv))
        e.w32(outp, (start + 2) & 0xffffffff)
        e.ret(eax=rv & 0xffffffff, argbytes=0)

    e.hook(0x62a690, stub)
    return [tab, buf, end, out]


S(0x628fc0, 'scan628fc0 (cdecl, four args, returns int)', 'cdecl', None, ret='eax', gen=_tok,
  note='u69 group 66; helper 0x62c640 runs as original code; 0x62a690 is a GUESS stub (cdecl, four args)')
